  if (ux === "CREATED") return { action: "CLOSE", level: "success", message: "Goods Delivery is already created." };
  if (status === "AWAITING_CONFIRMATION" || ux === "REQUIRES_REVIEW" || !ux) return { action: "STAY", level: "error", message: "An earlier save of this delivery is " + (status || "in an unknown state") + ": it cannot be saved again. Please contact your administrator." };
